import { CarData, Driver, ProcessedCarData } from '../types';

// --- EXPORTED UTILS ---

export const formatLapTime = (seconds: number): string => {
    if (typeof seconds !== 'number' || isNaN(seconds)) return "0:00.000";
    const m = Math.floor(seconds / 60);
    const s = (seconds % 60).toFixed(3);
    return `${m}:${s.padStart(6, '0')}`;
};

export const formatDelta = (seconds: number): string => {
    const sign = seconds > 0 ? "+" : "";
    return `${sign}${seconds.toFixed(3)}s`;
};

// --- INTERNAL HELPERS ---

/**
 * Robust Linear Interpolation (FastF1 style)
 */
export const interpolate = (x: number, xPoints: number[], yPoints: number[]): number => {
    if (xPoints.length === 0) return 0;
    if (x <= xPoints[0]) return yPoints[0];
    const len = xPoints.length;
    if (x >= xPoints[len - 1]) return yPoints[len - 1];

    let low = 0, high = len - 1;
    while (low < high) {
        const mid = (low + high) >>> 1;
        if (xPoints[mid] < x) low = mid + 1;
        else high = mid;
    }

    const i = low > 0 ? low - 1 : 0;
    const x0 = xPoints[i];
    const x1 = xPoints[i + 1];
    const y0 = yPoints[i];
    const y1 = yPoints[i + 1];

    if (x1 - x0 === 0) return y0;

    return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
};

/**
 * STEP 1: Enrich & Sanitize (Monotonicity Check)
 * Calculates Distance via Integration and enforces strictly increasing distance/time.
 */
export const enrichAndSanitize = (data: CarData[], lapStartDate: string, lapDuration: number) => {
    const len = data.length;
    if (len === 0) return null;

    // Sort chronologically
    const sortedData = [...data].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());

    const lapStartEpoch = new Date(lapStartDate).getTime();
    const rawPoints = [];

    let cumulativeDist = 0;

    // 1. Integration Loop
    for (let i = 0; i < len; i++) {
        const d = sortedData[i];
        if (i > 0) {
            const prev = sortedData[i-1];
            const timeDelta = (new Date(d.date).getTime() - new Date(prev.date).getTime()) / 1000;
            const vCurrent = d.speed / 3.6; // m/s
            const vPrev = prev.speed / 3.6;

            // Trapezoidal integration: dist += ((v_curr + v_prev) / 2) * delta_t
            const distDelta = ((vCurrent + vPrev) / 2) * timeDelta;

            // Physics filter: discard impossible jumps (>150m/s is 540km/h)
            if (distDelta >= 0 && distDelta < 150) { 
                cumulativeDist += distDelta;
            }
        }

        // Calculate relative time from Lap Start
        const t = (new Date(d.date).getTime() - lapStartEpoch) / 1000;

        // Filter to slightly wider than lap window
        if (t >= -2.0 && t <= lapDuration + 2.0) {
            rawPoints.push({ ...d, calculatedDistance: cumulativeDist, relativeTime: t });
        }
    }

    if (rawPoints.length < 10) return null;

    // 2. Monotonicity Enforcement
    const cleanPoints: ProcessedCarData[] = [];

    let zeroRefIndex = rawPoints.findIndex(p => p.relativeTime >= 0);
    if (zeroRefIndex === -1) zeroRefIndex = 0;

    const originDist = rawPoints[zeroRefIndex].calculatedDistance;
    const originTime = rawPoints[zeroRefIndex].relativeTime;

    let maxDist = -Infinity;
    let maxTime = -Infinity;

    for (const p of rawPoints) {
        const relDist = p.calculatedDistance - originDist;
        const relTime = p.relativeTime - originTime;

        // Strict increasing check
        if (relDist > maxDist + 0.0001 && relTime > maxTime + 0.0001) {
            maxDist = relDist;
            maxTime = relTime;

            cleanPoints.push({
                ...p,
                calculatedDistance: relDist,
                relativeTime: relTime
            });
        }
    }

    if (cleanPoints.length < 2) return null;

    return {
        processed: cleanPoints,
        totalDist: cleanPoints[cleanPoints.length - 1].calculatedDistance,
        totalTime: cleanPoints[cleanPoints.length - 1].relativeTime
    };
};

/**
 * STEP 2 & 3: Master Axis Resampling & Bias Corrected Delta
 */
const buildFastF1Grid = (
    inputs: { traceId: string; processed: ProcessedCarData[]; totalDist: number; totalTime: number }[]
) => {
    if (inputs.length === 0) return [];

    let refIndex = 0;
    let minTime = Infinity;

    inputs.forEach((input, idx) => {
        const duration = input.totalTime;
        if (duration < minTime) {
            minTime = duration;
            refIndex = idx;
        }
    });

    const refInput = inputs[refIndex];
    const refPoints = refInput.processed;

    const tracesData = inputs.map(input => ({
        id: input.traceId,
        dists: input.processed.map(p => p.calculatedDistance),
        times: input.processed.map(p => p.relativeTime),
        speeds: input.processed.map(p => p.speed),
        rpms: input.processed.map(p => p.rpm),
        gears: input.processed.map(p => p.n_gear),
        throttles: input.processed.map(p => p.throttle),
        brakes: input.processed.map(p => p.brake),
        drs: input.processed.map(p => p.drs),
    }));

    const combinedData = [];

    for (let i = 0; i < refPoints.length; i++) {
        const refP = refPoints[i];
        const dist = refP.calculatedDistance;
        if (dist < 0) continue;

        const row: any = { distance: dist };

        tracesData.forEach(trace => {
            const id = trace.id;
            row[`speed_${id}`] = Math.round(interpolate(dist, trace.dists, trace.speeds));
            row[`rpm_${id}`] = Math.round(interpolate(dist, trace.dists, trace.rpms));
            row[`throttle_${id}`] = Math.round(interpolate(dist, trace.dists, trace.throttles));
            row[`brake_${id}`] = Math.round(interpolate(dist, trace.dists, trace.brakes));
            row[`gear_${id}`] = Math.round(interpolate(dist, trace.dists, trace.gears));
            const drs = interpolate(dist, trace.dists, trace.drs);
            row[`drs_${id}`] = drs > 8 ? 1 : 0;
        });

        combinedData.push(row);
    }

    return combinedData;
};

// --- MAIN PIPELINE EXPORT ---

export const processTelemetryData = (
    inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
    const enrichedInputs = [];
    for (const input of inputs) {
        const result = enrichAndSanitize(input.data, input.lapStartDate, input.lapDuration);
        if (result) {
            enrichedInputs.push({ 
                traceId: input.traceId, 
                processed: result.processed, 
                totalDist: result.totalDist,
                totalTime: result.totalTime
            });
        }
    }
    if (enrichedInputs.length === 0) return [];
    return buildFastF1Grid(enrichedInputs);
};

import { GoogleGenAI, Type } from "@google/genai";
import { Driver, Lap, TelemetryPoint } from "../types";

// F1 telemetry analysis is a complex reasoning task
const ANALYSIS_MODEL = 'gemini-3-pro-preview';

export const analyzeTelemetry = async (
    inputs: { driver: Driver, lap: Lap, telemetry: TelemetryPoint[], label: string }[]
) => {
    // Initializing directly with process.env.API_KEY as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    if (inputs.length === 0) return { summary: "No data.", keyInsights: [], verdict: "N/A" };

    // Identify fastest lap
    const sortedInputs = [...inputs].sort((a, b) => a.lap.lap_duration - b.lap.lap_duration);
    const bestInput = sortedInputs[0];
    const bestDriver = bestInput.driver;

    // Helper to calc stats
    const calcStats = (data: TelemetryPoint[]) => {
        if (!data || data.length === 0) return { maxSpeed: 0, avgSpeed: '0', avgThrottle: '0', heavyBrakingZones: 0 };
        const maxSpeed = Math.max(...data.map(d => d.speed));
        const avgSpeed = data.reduce((a, b) => a + b.speed, 0) / data.length;
        const avgThrottle = data.reduce((a, b) => a + b.throttle, 0) / data.length;
        const heavyBrakingZones = data.filter(d => d.brake > 80).length;
        return { maxSpeed, avgSpeed: avgSpeed.toFixed(1), avgThrottle: avgThrottle.toFixed(1), heavyBrakingZones };
    };

    let prompt = `Act as a Formula 1 Race Engineer. Analyze the telemetry data for the following ${inputs.length} laps.\n\n`;

    prompt += `BENCHMARK LAP: ${bestInput.label} - ${bestDriver.full_name} (${bestDriver.team_name})\n`;
    prompt += `Lap Time: ${bestInput.lap.lap_duration}s | S1: ${bestInput.lap.duration_sector_1}s | S2: ${bestInput.lap.duration_sector_2}s | S3: ${bestInput.lap.duration_sector_3}s\n`;
    const bestStats = calcStats(bestInput.telemetry);
    prompt += `Stats: Max Speed ${bestStats.maxSpeed}km/h, Avg Speed ${bestStats.avgSpeed}km/h.\n\n`;

    if (inputs.length > 1) {
        prompt += `COMPARISON:\n`;
        sortedInputs.slice(1).forEach(input => {
            const diff = input.lap.lap_duration - bestInput.lap.lap_duration;
            const stats = calcStats(input.telemetry);
            prompt += `- ${input.label}: +${diff.toFixed(3)}s slower. (Max Speed: ${stats.maxSpeed}km/h). Sector Delta: Compare where they lost time.\n`;
        });

        prompt += `\nTASK:
        1. Explain why the Benchmark Lap was faster. Focus on cornering speed vs straight line speed.
        2. Identify if the slower laps were losing time in specific sectors or due to driving style (throttle application/braking).
        3. Provide a concise technical verdict.
        `;
    } else {
         prompt += `\nTASK:
        1. Analyze the lap performance based on the sectors and speed.
        2. Characterize the driving style.
        3. Identify potential areas for improvement.
        `;
    }

    prompt += `Provide the response in JSON format with fields: 
    - 'summary' (A concise 2-sentence summary), 
    - 'keyInsights' (3-4 bullet points of specific technical observations), 
    - 'verdict' (A final definitive statement).`;

    try {
        const response = await ai.models.generateContent({
            model: ANALYSIS_MODEL,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        summary: { type: Type.STRING },
                        keyInsights: { type: Type.ARRAY, items: { type: Type.STRING } },
                        verdict: { type: Type.STRING }
                    }
                }
            }
        });

        // Use response.text property directly
        const text = response.text;
        if (text) {
            return JSON.parse(text);
        }
        throw new Error("No response text");

    } catch (error) {
        console.error("Gemini Analysis Error:", error);
        return {
            summary: "Analysis unavailable due to high demand.",
            keyInsights: ["Could not retrieve AI data.", "Please try again later."],
            verdict: "Data Unavailable"
        };
    }
};

