export const formatLapTime = (seconds: number): string => {
  if (typeof seconds !== 'number' || isNaN(seconds)) return "0:00.000";
  const m = Math.floor(seconds / 60);
  const s = (seconds % 60).toFixed(3);
  return `${m}:${s.padStart(6, '0')}`;
};

/**
 * Robust Linear Interpolation (FastF1 style)
 */
export const interpolate = (x: number, xPoints: number[], yPoints: number[]): number => {
  if (xPoints.length === 0) return 0;
  if (x <= xPoints[0]) return yPoints[0];
  const len = xPoints.length;
  if (x >= xPoints[len - 1]) return yPoints[len - 1];

  let low = 0, high = len - 1;
  while (low < high) {
    const mid = (low + high) >>> 1;
    if (xPoints[mid] < x) low = mid + 1;
    else high = mid;
  }

  const i = low > 0 ? low - 1 : 0;
  const x0 = xPoints[i];
  const x1 = xPoints[i + 1];
  const y0 = yPoints[i];
  const y1 = yPoints[i + 1];

  if (x1 - x0 === 0) return y0;
  return y0 + (x - x0) * (y1 - y0) / (x1 - x0);
};

/**
 * Integration & Sanitization
 * Uses Trapezoidal Rule to calculate distance from speed.
 */
export const enrichAndSanitize = (data: CarData[], lapStartDate: string, lapDuration: number) => {
  if (!data || data.length < 5) return null;

  const sortedData = [...data].sort((a, b) => new Date(a.date).getTime() - new Date(b.date).getTime());
  const lapStartEpoch = new Date(lapStartDate).getTime();
  const rawPoints: ProcessedCarData[] = [];
  let cumulativeDist = 0;

  for (let i = 0; i < sortedData.length; i++) {
    const curr = sortedData[i];
    if (i > 0) {
      const prev = sortedData[i - 1];
      const timeDelta = (new Date(curr.date).getTime() - new Date(prev.date).getTime()) / 1000;
      const vCurr = curr.speed / 3.6; // m/s
      const vPrev = prev.speed / 3.6; // m/s

      // Trapezoidal Rule: dist += ((v1 + v2) / 2) * dt
      const distStep = ((vCurr + vPrev) / 2) * timeDelta;

      // Filter GPS drift/errors (>100m in one step ~ 360km/h for 1s)
      if (distStep >= 0 && distStep < 120) {
        cumulativeDist += distStep;
      }
    }

    const t = (new Date(curr.date).getTime() - lapStartEpoch) / 1000;
    rawPoints.push({
      ...curr,
      calculatedDistance: cumulativeDist,
      relativeTime: t
    });
  }

  // Filter to the lap window with small buffer
  const lapWindow = rawPoints.filter(p => p.relativeTime >= -1.0 && p.relativeTime <= lapDuration + 1.0);
  if (lapWindow.length < 10) return null;

  // Enforce monotonicity
  const clean: ProcessedCarData[] = [];
  let maxD = -1;
  let maxT = -Infinity;

  const refDist = lapWindow[0].calculatedDistance;

  for (const p of lapWindow) {
    const d = p.calculatedDistance - refDist;
    const t = p.relativeTime;
    if (d > maxD && t > maxT) {
      maxD = d;
      maxT = t;
      clean.push({ ...p, calculatedDistance: d });
    }
  }

  return {
    processed: clean,
    totalDist: clean[clean.length - 1].calculatedDistance,
    totalTime: clean[clean.length - 1].relativeTime
  };
};

export const processTelemetryData = (
  inputs: { driver: Driver; data: CarData[]; lapStartDate: string; lapDuration: number; traceId: string }[]
) => {
  const enriched = inputs.map(i => {
    const res = enrichAndSanitize(i.data, i.lapStartDate, i.lapDuration);
    return res ? { ...res, traceId: i.traceId } : null;
  }).filter((x): x is NonNullable<typeof x> => x !== null);

  if (enriched.length === 0) return [];

  // Use fastest lap as reference for master axis
  const ref = enriched.reduce((prev, curr) => (curr.totalTime < prev.totalTime ? curr : prev));
  const masterAxis = Array.from({ length: 600 }, (_, i) => (i * ref.totalDist) / 599);

  return masterAxis.map(d => {
    const row: any = { distance: d };
    enriched.forEach(e => {
      const id = e.traceId;
      const dists = e.processed.map(p => p.calculatedDistance);
      row[`speed_${id}`] = Math.round(interpolate(d, dists, e.processed.map(p => p.speed)));
      row[`throttle_${id}`] = Math.round(interpolate(d, dists, e.processed.map(p => p.throttle)));
      row[`brake_${id}`] = Math.round(interpolate(d, dists, e.processed.map(p => p.brake)));
      row[`rpm_${id}`] = Math.round(interpolate(d, dists, e.processed.map(p => p.rpm)));
      row[`gear_${id}`] = Math.round(interpolate(d, dists, e.processed.map(p => p.n_gear)));
    });
    return row;
  });
};

import { StagedLap, ProcessedCarData, DeltaTrace } from '../types';
import { interpolate } from './telemetryUtils';

export function generateDeltaAnalysis(
  stagedLaps: StagedLap[],
  telemetryMap: Map<string, ProcessedCarData[]>
) {
  if (stagedLaps.length < 2) return null;

  // 1. Reference Selection (Fastest)
  const sortedLaps = [...stagedLaps].sort((a, b) => a.lap.lap_duration - b.lap.lap_duration);
  const refLap = sortedLaps[0];
  const refData = telemetryMap.get(refLap.id);

  if (!refData || refData.length < 50) return null;

  const totalDist = refData[refData.length - 1].calculatedDistance;
  const masterDistances = Array.from({ length: 600 }, (_, i) => (i * totalDist) / 599);

  const refDists = refData.map(p => p.calculatedDistance);
  const refTimes = refData.map(p => p.relativeTime);
  const masterRefTimes = masterDistances.map(d => interpolate(d, refDists, refTimes));

  // 2. Calculate Deltas for each comparison lap
  const deltaTraces: DeltaTrace[] = stagedLaps.map(sl => {
    const compData = telemetryMap.get(sl.id);
    if (!compData || compData.length < 50) {
      return { traceId: sl.id, driverAcronym: sl.driver.name_acronym, lapNumber: sl.lap.lap_number, deltas: [], isReference: sl.id === refLap.id };
    }

    const compDists = compData.map(p => p.calculatedDistance);
    const compTimes = compData.map(p => p.relativeTime);
    const masterCompTimes = masterDistances.map(d => interpolate(d, compDists, compTimes));

    // Drift Correction
    const graphGap = masterCompTimes[masterCompTimes.length - 1] - masterRefTimes[masterRefTimes.length - 1];
    const trueGap = sl.lap.lap_duration - refLap.lap.lap_duration;
    const driftBias = trueGap - graphGap;

    const deltas = masterDistances.map((d, i) => {
      const rawDelta = masterCompTimes[i] - masterRefTimes[i];
      // Distribute integration bias linearly over distance
      const correction = (driftBias * d) / totalDist;
      return rawDelta + correction;
    });

    return {
      traceId: sl.id,
      driverAcronym: sl.driver.name_acronym,
      lapNumber: sl.lap.lap_number,
      deltas,
      isReference: sl.id === refLap.id
    };
  });

  return { masterDistances, deltaTraces, referenceLap: refLap };
}

import React, { useState, useMemo, useRef, useLayoutEffect } from 'react';
import ReactApexChart from 'react-apexcharts';
import { ApexOptions } from 'apexcharts';
import { motion, AnimatePresence } from 'framer-motion';
import { StagedLap, DeltaTrace } from '../types';

interface DeltaChartProps {
  masterDistances: number[];
  deltaTraces: DeltaTrace[];
  referenceLap: StagedLap;
  colors: string[];
}

const ResponsiveApexChart: React.FC<{
  options: ApexOptions;
  series: ApexOptions['series'];
  type: "line" | "area" | "bar";
}> = ({ options, series, type }) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const [shouldRender, setShouldRender] = useState(false);

  useLayoutEffect(() => {
    if (!containerRef.current) return;
    const observer = new ResizeObserver((entries) => {
      if (entries[0].contentRect.width > 0 && entries[0].contentRect.height > 0) {
        requestAnimationFrame(() => setShouldRender(true));
      }
    });
    observer.observe(containerRef.current);
    return () => observer.disconnect();
  }, []);

  return (
    <div ref={containerRef} className="w-full h-full min-h-[50px]">
      {shouldRender && (
        <ReactApexChart options={options} series={series} type={type} height="100%" width="100%" />
      )}
    </div>
  );
};

const DeltaChart: React.FC<DeltaChartProps> = ({ masterDistances, deltaTraces, referenceLap, colors }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [hiddenIds, setHiddenIds] = useState<Set<string>>(new Set());

  const toggleTrace = (id: string) => {
    const next = new Set(hiddenIds);
    if (next.has(id)) next.delete(id);
    else next.add(id);
    setHiddenIds(next);
  };

  const { series, chartColors } = useMemo(() => {
    const activeSeries: any[] = [];
    const activeColors: string[] = [];
    deltaTraces.forEach((trace, idx) => {
      if (hiddenIds.has(trace.traceId) || trace.isReference) return;
      activeSeries.push({
        name: `${trace.driverAcronym} (L${trace.lapNumber})`,
        data: masterDistances.map((d, i) => [d, trace.deltas[i]])
      });
      activeColors.push(colors[idx]);
    });
    return { series: activeSeries, chartColors: activeColors };
