    xaxis: {
      type: 'numeric',
      labels: {
        style: { colors: '#94a3b8', fontFamily: 'JetBrains Mono' },
        formatter: (val) => `${Math.round(Number(val))}m`
      }
    },
    yaxis: {
      labels: {
        style: { colors: '#94a3b8', fontFamily: 'JetBrains Mono' },
        formatter: (val) => `${Number(val) > 0 ? '+' : ''}${Number(val).toFixed(3)}s`
      },
      title: { text: 'Delta Time (s)', style: { color: '#64748b', fontSize: '10px' } }
    },
    legend: { show: false },
    tooltip: {
      theme: 'dark',
      x: { formatter: (val) => `Distance: ${Math.round(Number(val))}m` },
      y: { formatter: (val) => `${Number(val) > 0 ? '+' : ''}${Number(val).toFixed(3)}s` }
    }
  }), [chartColors, isExpanded]);

  return (
    <>
      <div className="w-full h-[340px] bg-f1-surface border border-white/5 rounded-lg p-5 flex flex-col mb-8 shadow-xl">
        <div className="flex justify-between items-center mb-6 shrink-0">
          <div className="flex items-center gap-3">
            <h3 className="text-xs font-bold uppercase tracking-widest text-f1-red">Delta Analysis</h3>
            <span className="text-[10px] text-f1-muted font-bold uppercase">Ref: {referenceLap.driver.name_acronym}</span>
          </div>
          <div className="flex gap-2">
            {deltaTraces.map((t, idx) => (
              !t.isReference && (
                <button
                  key={t.traceId}
                  onClick={() => toggleTrace(t.traceId)}
                  className={`flex items-center gap-1.5 px-2 py-1 rounded text-[9px] font-bold uppercase transition-all ${hiddenIds.has(t.traceId) ? 'opacity-30' : 'bg-white/5'}`}
