              </svg>
            </button>
          </div>
        </div>
        <div className="flex-1 w-full overflow-hidden">
          <ResponsiveApexChart options={options} series={series} type="area" />
        </div>
      </div>

      <AnimatePresence>
        {isExpanded && (
          <div className="fixed inset-0 z-[100] flex items-center justify-center p-4">
            <motion.div initial={{ opacity: 0 }} animate={{ opacity: 1 }} exit={{ opacity: 0 }} onClick={() => setIsExpanded(false)} className="absolute inset-0 bg-black/90 backdrop-blur-sm" />
            <motion.div initial={{ scale: 0.95, opacity: 0 }} animate={{ scale: 1, opacity: 1 }} exit={{ scale: 0.95, opacity: 0 }} className="relative w-full max-w-7xl h-[85vh] bg-f1-dark border border-f1-border rounded-xl p-6 shadow-2xl flex flex-col">
              <div className="flex justify-between items-center mb-6">
                <h3 className="text-lg font-bold uppercase tracking-widest text-white">Delta Analysis</h3>
                <button onClick={() => setIsExpanded(false)} className="p-3 text-f1-muted hover:text-white transition-all">
                  <svg className="w-6 h-6" fill="none" viewBox="0 0 24 24" stroke="currentColor"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg>
                </button>
              </div>
              <div className="flex-1 bg-black/40 rounded-lg p-2 border border-white/5">
                <ResponsiveApexChart options={options} series={series} type="area" />
              </div>
            </motion.div>
          </div>
        )}
      </AnimatePresence>
    </>
  );
};

export default DeltaChart;

import React, { useState, useEffect, useCallback, useMemo, useRef } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { getSessions, getDrivers, getLaps, getCarTelemetry, getLatestSession } from './services/openf1Service';
import { analyzeTelemetry } from './services/geminiService';
import { Session, Driver, Lap, AIAnalysisResult, StagedLap, ProcessedCarData } from './types';
import SessionSelector from './components/SessionSelector';
import TelemetrySingleChart from './components/TelemetrySingleChart';
import AIAnalysis from './components/AIAnalysis';
import LapHistoryChart from './components/LapHistoryChart';
import DeltaChart from './components/DeltaChart';
import DriverSelector from './components/DriverSelector';
import { processTelemetryData, formatLapTime, enrichAndSanitize } from './utils/telemetryUtils';
import { generateDeltaAnalysis } from './utils/deltaCalculator';
import { getTeamColors } from './utils/teamColors';

const CURRENT_YEAR = new Date().getFullYear();
const AVAILABLE_YEARS = Array.from({ length: 3 }, (_, i) => CURRENT_YEAR - i);
const MAX_LAPS = 8;

export const App: React.FC = () => {
  const [selectedYear, setSelectedYear] = useState<number>(CURRENT_YEAR);
  const [sessions, setSessions] = useState<Session[]>([]);
  const [selectedSession, setSelectedSession] = useState<Session | null>(null);
  const [allDrivers, setAllDrivers] = useState<Driver[]>([]);
  const [selectedDrivers, setSelectedDrivers] = useState<Driver[]>([]);
  const [lapsData, setLapsData] = useState<Map<number, Lap[]>>(new Map());
  const [stagedLaps, setStagedLaps] = useState<StagedLap[]>([]);
  const [telemetryData, setTelemetryData] = useState<any[]>([]);
  const [processedTelemetryMap, setProcessedTelemetryMap] = useState<Map<string, ProcessedCarData[]>>(new Map());
  const [deltaAnalysis, setDeltaAnalysis] = useState<any>(null);
  const [loadingLaps, setLoadingLaps] = useState(false);
  const [loadingTelemetry, setLoadingTelemetry] = useState(false);
  const [loadingSessions, setLoadingSessions] = useState(false);
  const [aiResult, setAiResult] = useState<AIAnalysisResult | null>(null);
  const [analyzing, setAnalyzing] = useState(false);

  useEffect(() => {
    const init = async () => {
      setLoadingSessions(true);
      const latest = await getLatestSession();
      if (latest) {
        setSelectedYear(latest.year);
        const all = await getSessions(latest.year);
        setSessions(all);
        setSelectedSession(latest);
      }
      setLoadingSessions(false);
    };
    init();
  }, []);

  useEffect(() => {
    if (!selectedSession) return;
    const loadDrivers = async () => {
      const d = await getDrivers(selectedSession.session_key);
      const unique = d.filter((v, i, a) => a.findIndex(t => t.driver_number === v.driver_number) === i);
      setAllDrivers(unique);
      setSelectedDrivers([]);
      setLapsData(new Map());
      setStagedLaps([]);
      setTelemetryData([]);
    };
    loadDrivers();
  }, [selectedSession]);

  const loadLapHistory = useCallback(async () => {
    if (!selectedSession || selectedDrivers.length === 0) return;
    setLoadingLaps(true);
    const newLapsMap = new Map<number, Lap[]>();
    await Promise.all(selectedDrivers.map(async (d) => {
      const laps = await getLaps(selectedSession.session_key, d.driver_number);
      newLapsMap.set(d.driver_number, laps.filter(l => l.lap_duration > 0));
    }));
    setLapsData(newLapsMap);
    setLoadingLaps(false);
  }, [selectedSession, selectedDrivers]);

  const syncTelemetry = async () => {
    if (!selectedSession || stagedLaps.length === 0) return;
    setLoadingTelemetry(true);
    setDeltaAnalysis(null);
    const newMap = new Map<string, ProcessedCarData[]>();

    try {
      const inputs = await Promise.all(stagedLaps.map(async (sl) => {
        const { driver, lap } = sl;
        const raw = await getCarTelemetry(selectedSession.session_key, driver.driver_number, lap.date_start, new Date(new Date(lap.date_start).getTime() + (lap.lap_duration + 2) * 1000).toISOString());
        const res = enrichAndSanitize(raw, lap.date_start, lap.lap_duration);
        if (res) newMap.set(sl.id, res.processed);
        return { driver, data: raw, lapStartDate: lap.date_start, lapDuration: lap.lap_duration, traceId: `${driver.name_acronym}_L${lap.lap_number}` };
      }));

      setProcessedTelemetryMap(newMap);
      setTelemetryData(processTelemetryData(inputs));
      if (stagedLaps.length >= 2) {
        setDeltaAnalysis(generateDeltaAnalysis(stagedLaps, newMap));
      }
    } catch (e) {
      console.error(e);
    } finally {
      setLoadingTelemetry(false);
    }
  };

  const handleToggleLap = useCallback((driver: Driver, lap: Lap) => {
    const id = `${driver.driver_number}_${lap.lap_number}`;
    setStagedLaps(prev => {
      const exists = prev.find(s => s.id === id);
      if (exists) return prev.filter(s => s.id !== id);
      if (prev.length < MAX_LAPS) return [...prev, { id, driver, lap, color: '' }];
      return prev;
    });
  }, []);

  const fetchAIAnalysis = async () => {
    if (stagedLaps.length === 0 || telemetryData.length === 0) return;
    setAnalyzing(true);
    const colors = getTeamColors(stagedLaps.map(s => s.driver));
    const inputs = stagedLaps.map((sl, idx) => {
      const traceId = `${sl.driver.name_acronym}_L${sl.lap.lap_number}`;
      const sample = telemetryData.filter((_, i) => i % 10 === 0).map(row => ({
        distance: row.distance,
        speed: row[`speed_${traceId}`] || 0,
        throttle: row[`throttle_${traceId}`] || 0,
        brake: row[`brake_${traceId}`] || 0,
        rpm: row[`rpm_${traceId}`] || 0,
        gear: row[`gear_${traceId}`] || 0,
        driver: sl.driver.name_acronym,
        color: colors[idx]
      }));
      return { driver: sl.driver, lap: sl.lap, telemetry: sample as any, label: `${sl.driver.name_acronym} (L${sl.lap.lap_number})` };
    });
    const res = await analyzeTelemetry(inputs);
    setAiResult(res);
    setAnalyzing(false);
  };

  const allColors = useMemo(() => getTeamColors(stagedLaps.map(s => s.driver)), [stagedLaps]);

  return (
    <div className="min-h-screen w-full bg-[#09090b] text-white flex flex-col font-sans selection:bg-f1-red/30">
      <header className="sticky top-0 z-50 w-full bg-[#09090b] border-b border-white/5 px-6 py-4 flex items-center justify-between shadow-xl">
        <div className="flex items-center gap-3">
          <div className="w-8 h-8 bg-f1-red rounded-sm flex items-center justify-center">
            <span className="font-mono font-bold text-lg">S</span>
          </div>
          <h1 className="text-xl font-bold tracking-tight uppercase">StintLogic<span className="text-f1-red">.com</span></h1>
        </div>
      </header>

      <main className="flex-1 w-full p-6 space-y-6">
        <div className="container mx-auto">
          <SessionSelector 
            years={AVAILABLE_YEARS} selectedYear={selectedYear} onSelectYear={setSelectedYear}
            sessions={sessions} selectedSession={selectedSession} onSelectSession={setSelectedSession}
            isLoading={loadingSessions} onRandomize={() => {}} onRefresh={() => {}}
          />

          <div className="grid grid-cols-1 lg:grid-cols-4 gap-8">
            <aside className="lg:col-span-1 space-y-6">
              <DriverSelector allDrivers={allDrivers} selectedDrivers={selectedDrivers} onToggleDriver={d => setSelectedDrivers(prev => prev.find(x => x.driver_number === d.driver_number) ? prev.filter(x => x.driver_number !== d.driver_number) : [...prev, d])} />
              <button onClick={loadLapHistory} disabled={selectedDrivers.length === 0 || loadingLaps} className="w-full py-3 bg-f1-red font-bold text-xs uppercase tracking-widest rounded disabled:opacity-50">
                {loadingLaps ? 'SYNCING...' : 'SYNC LAP HISTORY'}
              </button>
            </aside>

            <div className="lg:col-span-3 space-y-8">
              {lapsData.size > 0 && <LapHistoryChart selectedDrivers={selectedDrivers} lapsData={lapsData} stagedLaps={stagedLaps} onToggleLap={handleToggleLap} colors={[]} />}

              <div className="bg-f1-surface p-6 rounded-lg border border-white/5 shadow-2xl">
                <div className="flex justify-between items-center mb-6">
                  <h3 className="text-xs font-bold uppercase tracking-widest text-f1-muted">Comparison Workspace</h3>
                  <button onClick={syncTelemetry} disabled={stagedLaps.length === 0 || loadingTelemetry} className="px-6 py-2 bg-blue-600 text-white text-[10px] font-bold uppercase rounded hover:bg-blue-500 disabled:opacity-50">
                    {loadingTelemetry ? 'CALCULATING...' : 'ANALYZE TELEMETRY'}
                  </button>
                </div>
                <div className="grid grid-cols-2 md:grid-cols-4 gap-3">
                  {stagedLaps.map((sl, i) => (
                    <div key={sl.id} className="bg-white/5 p-3 rounded border-l-4" style={{ borderColor: allColors[i] }}>
                      <div className="text-[10px] text-f1-muted font-bold uppercase">{sl.driver.name_acronym} (L{sl.lap.lap_number})</div>
                      <div className="text-sm font-mono font-bold">{formatLapTime(sl.lap.lap_duration)}</div>
                    </div>
                  ))}
                </div>
              </div>

              {telemetryData.length > 0 && (
                <div className="space-y-6">
                  {deltaAnalysis && <DeltaChart masterDistances={deltaAnalysis.masterDistances} deltaTraces={deltaAnalysis.deltaTraces} referenceLap={deltaAnalysis.referenceLap} colors={allColors} />}
                  <TelemetrySingleChart title="Speed (km/h)" data={telemetryData} dataKey="speed" stagedLaps={stagedLaps} />
                  <TelemetrySingleChart title="Throttle (%)" data={telemetryData} dataKey="throttle" stagedLaps={stagedLaps} />
                  <TelemetrySingleChart title="Braking (%)" data={telemetryData} dataKey="brake" stagedLaps={stagedLaps} />
                  <div className="pt-10 flex flex-col items-center">
                    <button onClick={fetchAIAnalysis} disabled={analyzing} className="w-full max-w-lg py-4 bg-f1-surface border border-f1-red text-white font-bold uppercase text-xs rounded hover:bg-f1-red transition-all">
                      {analyzing ? 'AI IS THINKING...' : 'GET AI RACE ENGINEER ANALYSIS'}
                    </button>
                    <AIAnalysis analysis={aiResult} isLoading={analyzing} />
                  </div>
                </div>
              )}
            </div>
          </div>
        </div>
      </main>
    </div>
  );
};

import { GoogleGenAI, Type } from "@google/genai";
import { Driver, Lap, TelemetryPoint } from "../types";

// F1 telemetry analysis is a complex reasoning task
const ANALYSIS_MODEL = 'gemini-3-pro-preview';

export const analyzeTelemetry = async (
    inputs: { driver: Driver, lap: Lap, telemetry: TelemetryPoint[], label: string }[]
) => {
    // Initializing directly with process.env.API_KEY as per guidelines
    const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

    if (inputs.length === 0) return { summary: "No data.", keyInsights: [], verdict: "N/A" };

    // Identify fastest lap
    const sortedInputs = [...inputs].sort((a, b) => a.lap.lap_duration - b.lap.lap_duration);
    const bestInput = sortedInputs[0];
    const bestDriver = bestInput.driver;

    // Helper to calc stats
    const calcStats = (data: TelemetryPoint[]) => {
        if (!data || data.length === 0) return { maxSpeed: 0, avgSpeed: '0', avgThrottle: '0', heavyBrakingZones: 0 };
        // FIX: Explicitly cast telemetry values to number to satisfy numeric operations as TelemetryPoint properties can be string | number
        const maxSpeed = Math.max(...data.map(d => Number(d.speed)));
        const avgSpeed = data.reduce((a, b) => a + Number(b.speed), 0) / data.length;
        const avgThrottle = data.reduce((a, b) => a + Number(b.throttle), 0) / data.length;
        const heavyBrakingZones = data.filter(d => Number(d.brake) > 80).length;
        return { maxSpeed, avgSpeed: avgSpeed.toFixed(1), avgThrottle: avgThrottle.toFixed(1), heavyBrakingZones };
    };

    let prompt = `Act as a Formula 1 Race Engineer. Analyze the telemetry data for the following ${inputs.length} laps.\n\n`;

    prompt += `BENCHMARK LAP: ${bestInput.label} - ${bestDriver.full_name} (${bestDriver.team_name})\n`;
    prompt += `Lap Time: ${bestInput.lap.lap_duration}s | S1: ${bestInput.lap.duration_sector_1}s | S2: ${bestInput.lap.duration_sector_2}s | S3: ${bestInput.lap.duration_sector_3}s\n`;
    const bestStats = calcStats(bestInput.telemetry);
    prompt += `Stats: Max Speed ${bestStats.maxSpeed}km/h, Avg Speed ${bestStats.avgSpeed}km/h.\n\n`;

    if (inputs.length > 1) {
        prompt += `COMPARISON:\n`;
        sortedInputs.slice(1).forEach(input => {
            const diff = input.lap.lap_duration - bestInput.lap.lap_duration;
            const stats = calcStats(input.telemetry);
            prompt += `- ${input.label}: +${diff.toFixed(3)}s slower. (Max Speed: ${stats.maxSpeed}km/h). Sector Delta: Compare where they lost time.\n`;
        });

        prompt += `\nTASK:
        1. Explain why the Benchmark Lap was faster. Focus on cornering speed vs straight line speed.
        2. Identify if the slower laps were losing time in specific sectors or due to driving style (throttle application/braking).
        3. Provide a concise technical verdict.
        `;
    } else {
         prompt += `\nTASK:
        1. Analyze the lap performance based on the sectors and speed.
        2. Characterize the driving style.
        3. Identify potential areas for improvement.
        `;
    }

    prompt += `Provide the response in JSON format with fields: 
    - 'summary' (A concise 2-sentence summary), 
    - 'keyInsights' (3-4 bullet points of specific technical observations), 
    - 'verdict' (A final definitive statement).`;

    try {
        const response = await ai.models.generateContent({
            model: ANALYSIS_MODEL,
            contents: prompt,
            config: {
                responseMimeType: 'application/json',
                responseSchema: {
                    type: Type.OBJECT,
                    properties: {
                        summary: { type: Type.STRING },
                        keyInsights: { type: Type.ARRAY, items: { type: Type.STRING } },
                        verdict: { type: Type.STRING }
                    }
                }
            }
        });

        // Use response.text property directly
        const text = response.text;
        if (text) {
            return JSON.parse(text);
        }
        throw new Error("No response text");

    } catch (error) {
        console.error("Gemini Analysis Error:", error);
        return {
            summary: "Analysis unavailable due to high demand.",
            keyInsights: ["Could not retrieve AI data.", "Please try again later."],
            verdict: "Data Unavailable"
        };
    }
};
